class Values {
  #entries;
  constructor(entries = new Map()) {
    this.#entries = entries;
  }
  set(key, value) {
    const copy = new Map(this.#entries);
    copy.set(key, value);
    return new Values(copy);
  }
  get(key) {
    return this.#entries.get(key);
  }
  size() {
    return this.#entries.size;
  }
}

