let current;
function run(context, fn) {
  const previous = current;
  current = context;
  try {
    return fn();
  } finally {
    current = previous;
  }
}
const capture = () => current;
const runSnapshot = (snapshot, fn) => run(snapshot, fn);

const jobs = [];
run({ correlationId: "req-8" }, () => {
  const snapshot = capture();
  jobs.push(() => runSnapshot(snapshot, () => console.log("job sees", current?.correlationId ?? "nothing")));
