function moduleContextFor(id, declared, registry) {
  const allowed = new Set(declared);
  return {
    hasModule: (other) => allowed.has(other) && registry.has(other),
    getModule(other) {
      if (!allowed.has(other)) throw new Error(`Module "${id}" did not declare "${other}"`);
      return registry.get(other);
    },
  };
}

