function createApp(startModules) {
  const app = {
    state: "initialized",
    start() {
      if (app.state !== "initialized" && app.state !== "stopped") throw new Error(`cannot start from ${app.state}`);
      try {
        startModules();
        app.state = "running";
      } catch (error) {
        app.state = "failed";
        throw error;
      }
    },
    stop() {
      app.state = "stopped";
    },
  };
  return app;
}

let dbUp = false;
const app = createApp(() => { if (!dbUp) throw new Error("ECONNREFUSED"); });
for (const step of ["start", "start", "stop", "fix", "start"]) {
  if (step === "fix") { dbUp = true; continue; }
  try {
    app[step]();
  } catch (error) {
    console.log("error:", error.message);
  }
  console.log(step, "->", app.state);
}

