function scoped(factory) {
  const instances = new WeakMap();
  return (scopeKey) => {
    if (scopeKey === undefined) throw new Error("no active scope");
    if (!instances.has(scopeKey)) instances.set(scopeKey, factory());
    return instances.get(scopeKey);
  };
}

