function connectionModule(open) {
  let connection;
  return {
    initialize() {
      connection = open();
    },
    destroy() {
      if (connection === undefined) {
        console.log("nothing to close");
        return;
      }
      connection.close();
      connection = undefined;
    },
  };
}

